package com.school.management.entity; import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity public class Announcement { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String title; @Column(columnDefinition="TEXT") private String message; private String audience; private LocalDateTime createdAt=LocalDateTime.now(); public Announcement(){} public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getAudience(){return audience;} public void setAudience(String v){audience=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
